/work/lib/security/origin.ts.content:
import { AppError } from "@/lib/errors";

export function assertSameOrigin(request: Request): void {
  const origin = request.headers.get("origin");
  if (!origin) return;
  const expected = new URL(request.url).origin;
  if (origin !== expected) throw new AppError("VALIDATION_ERROR", "Cross-origin changes are not allowed.", 403);
}

/work/tests/unit/normalization.test.ts.content:
import assert from "node:assert/strict";
import test from "node:test";
import { normalizeTag, normalizeTags } from "../../lib/tags/normalize";
import { escapeLike, normalizeForSearch } from "../../lib/text/normalize";
import { fallbackTitle, normalizeUrl, UrlValidationError } from "../../lib/urls/normalize";

test("normalizes common URLs and strips fragments", () => {
  assert.equal(normalizeUrl("Example.COM/path#part").url, "https://example.com/path");
});

test("rejects unsupported schemes, credentials, and ports", () => {
  for (const value of ["file:///tmp/x", "https://a:b@example.com", "https://example.com:8443"]) {
    assert.throws(() => normalizeUrl(value), UrlValidationError);
  }
});

test("creates a readable fallback title", () => {
  assert.equal(fallbackTitle("https://www.example.com/guide/intro"), "intro");
});

test("normalizes Unicode search and tag keys", () => {
  assert.equal(normalizeForSearch("  Ｃafé  "), "café");
  assert.equal(normalizeTag("  Work   Notes ").name, "Work Notes");
  assert.equal(normalizeTags(["Work", "work"]).length, 1);
  assert.equal(escapeLike("50%_ok\\"), "50\\%\\_ok\\\\");
});

/work/lib/urls/normalize.ts.content:
const MAX_URL_LENGTH = 2048;

export class UrlValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "UrlValidationError";
  }
}

export type NormalizedUrl = { url: string; key: string; hostname: string };

export function normalizeUrl(input: string): NormalizedUrl {
  let candidate = input.trim();
  if (!candidate) throw new UrlValidationError("Enter a web address.");
  if (candidate.length > MAX_URL_LENGTH) throw new UrlValidationError("Web addresses must be 2,048 characters or fewer.");
  if (!/^[a-z][a-z\d+.-]*:/i.test(candidate)) candidate = `https://${candidate}`;

  let parsed: URL;
  try { parsed = new URL(candidate); } catch { throw new UrlValidationError("Enter a valid web address."); }
  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") throw new UrlValidationError("Only HTTP and HTTPS addresses are supported.");
  if (parsed.username || parsed.password) throw new UrlValidationError("Web addresses containing credentials are not supported.");
  if (!parsed.hostname) throw new UrlValidationError("Enter a web address with a valid host.");
  if (parsed.port && !((parsed.protocol === "http:" && parsed.port === "80") || (parsed.protocol === "https:" && parsed.port === "443"))) {
    throw new UrlValidationError("Web addresses using nonstandard ports are not supported.");
  }
  parsed.hash = "";
  parsed.hostname = parsed.hostname.toLowerCase();
  const normalized = parsed.toString();
  return { url: normalized, key: normalized, hostname: parsed.hostname };
}

export function fallbackTitle(value: string): string {
  try {
    const { url } = normalizeUrl(value);
    const parsed = new URL(url);
    const path = decodeURIComponent(parsed.pathname).replace(/\/+$/, "").split("/").filter(Boolean).pop();
    return (path || parsed.hostname.replace(/^www\./, "")).slice(0, 300);
  } catch {
    return "Untitled bookmark";
  }
}

