export function normalizeTag(value: string): { name: string; key: string } {
  const name = value.normalize("NFKC").trim().replace(/\s+/gu, " ");
  if (!name) throw new Error("Tags cannot be empty.");
  if (name.length > 50) throw new Error("Tags must be 50 characters or fewer.");
  return { name, key: normalizeForSearch(name) };
}

export function normalizeTags(values: string[]): Array<{ name: string; key: string }> {
  if (values.length > 50) throw new Error("A bookmark can have at most 50 tags.");
  const unique = new Map<string, { name: string; key: string }>();
