      title, titleSearch: normalizeForSearch(title), titleOrigin: input.titleOrigin,
      note: input.note, noteSearch: normalizeForSearch(input.note),
      ...(input.iconToken !== undefined ? { iconAsset: input.iconToken } : {}),
