      if (err.existingId) setError(`${err.message} Open the existing bookmark from your collection below.`); else setError(err.message);
      setMessage("");
    } finally { setBusy(false); }
  }

  if (!bookmark && !preview) return (
    <form className={`save-strip ${compact ? "compact" : ""}`} onSubmit={getPreview} aria-label="Save a link">
      <label htmlFor="bookmark-url">Paste a link to keep</label>
      <div className="url-row"><input id="bookmark-url" name="url" type="text" inputMode="url" autoComplete="url" required maxLength={2048} placeholder="https://example.com/article" value={url} onChange={(event) => setUrl(event.target.value)} /><button className="button primary" disabled={busy}>{busy ? "Finding details…" : "Preview link"}</button></div>
      {error && <p className="notice error" role="alert">{error}</p>}<LiveStatus message={message} />
    </form>
  );

  return (
    <form className="bookmark-form" onSubmit={save}>
      {!bookmark && preview && <MetadataPreview preview={preview} />}
      <div className="field"><label htmlFor="edit-url">Web address</label><input id="edit-url" value={url} maxLength={2048} required onChange={(e) => { setUrl(e.target.value); if (bookmark) setPreview(null); }} /></div>
      <div className="field"><label htmlFor="bookmark-title">Title</label><input id="bookmark-title" value={title} maxLength={300} required onChange={(e) => { setTitle(e.target.value); setTitleOrigin("user"); }} /><span className="field-hint">{title.length}/300</span></div>
      <div className="field"><label htmlFor="bookmark-note">Note <span>(optional)</span></label><textarea id="bookmark-note" value={note} maxLength={5000} rows={4} placeholder="Why is this worth keeping?" onChange={(e) => setNote(e.target.value)} /><span className="field-hint">{note.length}/5000</span></div>
      <div className="field"><span className="field-label">Tags <span>(optional)</span></span><TagInput tags={tags} onChange={setTags} /></div>
      {error && <p className="notice error" role="alert">{error}</p>}
      <div className="form-actions"><button className="button primary" disabled={busy}>{busy ? "Saving…" : bookmark ? "Save changes" : "Save bookmark"}</button>{!bookmark && <button className="button ghost" type="button" onClick={() => { setPreview(null); setTitle(""); setMessage(""); }}>Start over</button>}</div>
      <LiveStatus message={message} />
    </form>
  );
}
export type Bookmark = {
  id: string; url: string; title: string; titleOrigin: "fetched" | "fallback" | "user";
  note: string; iconPath?: string | null; tags: string[]; createdAt: string; updatedAt: string;
};

export type Preview = {
  normalizedUrl: string; title: string; titleOrigin: "fetched" | "fallback";
  iconToken?: string | null; warning?: string | null; existingBookmarkId?: string | null;
};

export type ApiError = { error?: { code?: string; message?: string; field?: string; existingId?: string } };

export async function jsonRequest<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, init);
  if (!response.ok) {
    let body: ApiError = {};
    try { body = await response.json() as ApiError; } catch { /* use generic message */ }
    const error = new Error(body.error?.message || "Something went wrong. Please try again.");
    Object.assign(error, { status: response.status, existingId: body.error?.existingId });
    throw error;
  }
  if (response.status === 204) return undefined as T;
  return response.json() as Promise<T>;
}
import { createHash, randomBytes } from "node:crypto";
import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import path from "node:path";
import sharp from "sharp";
import { fetchBounded, type MetadataFetcherOptions } from "./fetcher";

const ICON_LIMIT = 256 * 1024;
const TOKEN_TTL_MS = 15 * 60_000;
const tokens = new Map<string, { asset: string; expiresAt: number }>();

export async function retrieveIcon(url: string, options?: MetadataFetcherOptions, iconDir = path.join(process.cwd(), "data/icons")): Promise<string | null> {
  try {
    const fetched = await fetchBounded(url, { ...options, limits: { ...options?.limits, maxCompressedBytes: ICON_LIMIT, maxDecompressedBytes: ICON_LIMIT } }, "icon");
    if (fetched.contentType.includes("svg") || fetched.body.length > ICON_LIMIT) return null;
    const metadata = await sharp(fetched.body, { failOn: "error", limitInputPixels: 16_777_216 }).metadata();
    if (!["png", "jpeg", "gif", "webp", "ico"].includes(metadata.format ?? "")) return null;
    const png = await sharp(fetched.body, { failOn: "error" }).resize(64, 64, { fit: "contain", withoutEnlargement: true }).png({ compressionLevel: 9 }).toBuffer();
    const asset = `${createHash("sha256").update(png).digest("hex")}.png`;
    await mkdir(iconDir, { recursive: true });
    const temporary = path.join(iconDir, `.${asset}.${randomBytes(6).toString("hex")}.tmp`);
    await writeFile(temporary, png, { flag: "wx" });
    await rename(temporary, path.join(iconDir, asset)).catch(async (error: NodeJS.ErrnoException) => {
      if (error.code !== "EEXIST") throw error;
    });
    const token = randomBytes(24).toString("base64url");
    tokens.set(token, { asset, expiresAt: Date.now() + TOKEN_TTL_MS });
    return token;
  } catch { return null; }
}

export function redeemIconToken(token: string): string | null {
  if (!/^[A-Za-z0-9_-]{32}$/u.test(token)) return null;
  const entry = tokens.get(token);
  if (!entry || entry.expiresAt < Date.now()) { tokens.delete(token); return null; }
  return entry.asset;
}

export async function readIconAsset(asset: string, iconDir = path.join(process.cwd(), "data/icons")): Promise<Buffer | null> {
  if (!/^[a-f0-9]{64}\.png$/u.test(asset)) return null;
  try { return await readFile(path.join(iconDir, asset)); } catch { return null; }
}
