import Link from "next/link";
import type { Bookmark } from "./types";
import { DeleteBookmarkDialog } from "./delete-bookmark-dialog";

export function BookmarkCard({ bookmark, onDeleted, onTag }: { bookmark: Bookmark; onDeleted: () => void; onTag: (tag: string) => void }) {
  let host = bookmark.url; try { host = new URL(bookmark.url).hostname.replace(/^www\./, ""); } catch {}
  return <article className="bookmark-card">
    <div className="card-main"><img className="site-icon" src={bookmark.iconPath || "/generic-site-icon.svg"} alt="" width="38" height="38" onError={(e) => { e.currentTarget.src = "/generic-site-icon.svg"; }} /><div className="card-copy"><a className="bookmark-title" href={bookmark.url} target="_blank" rel="noopener noreferrer">{bookmark.title}<span className="external" aria-hidden="true">↗</span><span className="sr-only"> (opens in a new tab)</span></a><p className="bookmark-host">{host}</p>{bookmark.note && <p className="bookmark-note">{bookmark.note}</p>}{bookmark.tags.length > 0 && <ul className="tag-list card-tags" aria-label="Tags">{bookmark.tags.map((tag) => <li key={tag}><button className="tag static" onClick={() => onTag(tag)}>{tag}</button></li>)}</ul>}</div></div>
    <div className="card-actions"><Link className="text-button" href={`/bookmarks/${bookmark.id}/edit`}>Edit</Link><DeleteBookmarkDialog id={bookmark.id} title={bookmark.title} onDeleted={onDeleted} /></div>
  </article>;
}
"use client";

import * as AlertDialog from "@radix-ui/react-alert-dialog";
import { useState } from "react";
import { jsonRequest } from "./types";

export function DeleteBookmarkDialog({ id, title, onDeleted }: { id: string; title: string; onDeleted: () => void }) {
  const [busy, setBusy] = useState(false); const [error, setError] = useState("");
  async function remove() { setBusy(true); setError(""); try { await jsonRequest<void>(`/api/bookmarks/${id}`, { method: "DELETE" }); onDeleted(); } catch (e) { setError(e instanceof Error ? e.message : "Could not delete bookmark."); setBusy(false); } }
  return <AlertDialog.Root><AlertDialog.Trigger asChild><button className="text-button danger">Delete</button></AlertDialog.Trigger><AlertDialog.Portal><AlertDialog.Overlay className="dialog-overlay" /><AlertDialog.Content className="dialog" aria-describedby="delete-description"><span className="eyebrow">Delete bookmark</span><AlertDialog.Title>Remove “{title}”?</AlertDialog.Title><AlertDialog.Description id="delete-description">This removes the bookmark from your library. This action cannot be undone.</AlertDialog.Description>{error && <p role="alert" className="notice error">{error}</p>}<div className="dialog-actions"><AlertDialog.Cancel asChild><button className="button secondary" autoFocus disabled={busy}>Cancel</button></AlertDialog.Cancel><button className="button destructive" onClick={remove} disabled={busy}>{busy ? "Deleting…" : "Delete bookmark"}</button></div></AlertDialog.Content></AlertDialog.Portal></AlertDialog.Root>;
}
"use client";

import Link from "next/link";
import { useParams } from "next/navigation";
import { useEffect, useState } from "react";
import { BookmarkForm } from "../../../../components/bookmark-form";
import { jsonRequest, type Bookmark } from "../../../../components/types";

export default function EditBookmarkPage() {
  const { id } = useParams<{ id: string }>(); const [bookmark, setBookmark] = useState<Bookmark | null>(null); const [error, setError] = useState("");
  useEffect(() => { jsonRequest<Bookmark>(`/api/bookmarks/${id}`).then(setBookmark).catch((e) => setError(e instanceof Error ? e.message : "Bookmark not found.")); }, [id]);
  return <div className="narrow-page" data-harness-ready={bookmark || error ? "true" : undefined}><Link className="back-link" href="/">← Back to bookmarks</Link><span className="eyebrow">Edit bookmark</span><h1>Refine what you saved.</h1>{error ? <div className="notice error" role="alert">{error}</div> : bookmark ? <BookmarkForm bookmark={bookmark} /> : <p role="status">Loading bookmark…</p>}</div>;
}

